const body = $input.first().json.body || $input.first().json;
const fr = body.form_response || {};
const fields = (fr.definition && fr.definition.fields) || [];
const title = {};
fields.forEach(f => { title[f.id] = (f.title || '').toLowerCase(); });
const lead = { message: '' };
(fr.answers || []).forEach(a => {
  const t = title[a.field && a.field.id] || '';
  if (a.type === 'email') lead.email = a.email;
  else if (a.type === 'phone_number') lead.phone = a.phone_number;
  else if (a.type === 'text' || a.type === 'long_text') {
    if (!lead.name && t.includes('name')) lead.name = a.text;
    else if (!lead.company && t.includes('company')) lead.company = a.text;
    else lead.message += (lead.message ? '\n' : '') + (t ? t + ': ' : '') + a.text;
  }
});
if (!lead.name && lead.email) lead.name = lead.email.split('@')[0];
return [{ json: lead }];
